import json, sys, pathlib
sys.path.insert(0, "lib")
from snippets import code as lcode
SPEC = json.load(open("out/spec.json"))
BASE = open("inputs/mock_url.txt").read().strip().rstrip("/") + SPEC["base_path"]
SLOT = "freya-final-case"
N = {}

def C(body, use_lib=False):
    src = lcode(body, SPEC) if use_lib else "import json, re\nSPEC = json.loads(" + repr(json.dumps(SPEC)) + ")\n" + COMMON + body
    return src.replace("{{", "{ {").replace("}}", "} }")

COMMON = r'''
MON = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık']
def sd(s):
    try:
        d, m, y = str(s).strip().split('.')
        return '%d %s %s' % (int(d), MON[int(m)-1], y)
    except Exception:
        return str(s or '')
def ymd(s):
    try:
        d, m, y = str(s).strip().split('.'); return (int(y), int(m), int(d))
    except Exception: return None
def today():
    n = str(vars.get('now') or '')
    try: return (int(n[0:4]), int(n[5:7]), int(n[8:10]))
    except Exception: return None
def fnum(v):
    try: return float(str(v).replace(',', '.'))
    except Exception: return None
def amt(x):
    x = fnum(x) or 0.0
    neg = x < 0; x = abs(x)
    s = '%.2f' % x
    i, f = s.split('.')
    g = ''
    while len(i) > 3: g = '.' + i[-3:] + g; i = i[:-3]
    r = i + g + ('' if f == '00' else ',' + f)
    return ('eksi ' if neg else '') + r
def resp(node):
    p = node + '_response.data.'
    code = str(vars.get(p + 'result.returnCode') or vars.get(p + 'result.code') or '')
    return p + 'data.', code
def joinve(xs):
    return xs[0] if len(xs) == 1 else ', '.join(xs[:-1]) + ' ve ' + xs[-1]
'''

def api(name, path, body, nxt):
    props = {k: {"type": "string", "default": v} for k, v in body.items()}
    N[name] = {"name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": nxt,
        "on_enter": {"type": "silent"},
        "pre_actions": [{"type": "function", "config": {"timeoutMs": 20000, "maxRetries": 0}, "function": {
            "name": name, "handler": "__function__:api_call", "description": path,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + path},
                "method": {"type": "string", "default": "POST"},
                "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}, "Accept": {"type": "string", "default": "application/json"}}},
                "body": {"type": "object", "required": ["data"], "properties": {
                    "data": {"type": "object", "properties": props},
                    "call": {"type": "object", "properties": {"lang": {"type": "string", "default": "tr"}}}}}}}}}],
        "response_mapping": [], "transitions": [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}]}

def eq(var, val): return {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": val}]}

def codenode(name, body, routes, default, use_lib=False):
    tr = [{"target_node": t, "description": "%s=%s" % (v, val), "condition": eq(v, val)} for (v, val, t) in routes]
    tr.append({"target_node": default, "description": "always", "condition": {"operator": "always"}})
    N[name] = {"name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": default,
        "on_enter": {"type": "silent"},
        "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
            "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": C(body, use_lib)},
                                                            "timeout_ms": {"type": "number", "default": 10000}}}}}],
        "transitions": tr}

TALK = ("Sen Freya Bank'ın sesli asistanısın. Türkçe ve 'siz' diliyle konuş. Az önce müşteriye şu metin okundu:\n\"{{say}}\"\n"
        "Say exactly this text. Never promise a transfer, a callback or any other action that the text does not state. "
        "Müşteri tekrar isterse metni kelimesi kelimesine tekrar et. Anlaşılmayan bir yanıtta yalnızca son soruyu kısaca tekrar sor. "
        "Kart numarasının son dört hanesi dışında hiçbir hanesini asla söyleme. Ödeme kanallarını anlatma. Rakam, tarih veya adres uydurma. "
        "Müşteri şifre veya tam kart numarası söylerse onu tekrarlama ve bankanın asla şifre sormadığını hatırlat.")

def talk(name, enum_name, values, desc, routes, extra=None):
    ex = [{"name": enum_name, "type": "string", "enum_values": ["none"] + values, "description": desc, "min_confidence": 0.5}]
    if extra: ex += extra
    tr = [{"target_node": t, "description": "%s=%s" % (v, val), "condition": eq(v, val)} for (v, val, t) in routes]
    N[name] = {"name": name, "node_type": "conversation", "on_enter": {"type": "tts", "text": "{{say}}"},
        "task_message": TALK, "extraction_schema": ex, "transitions": tr, "tools": [],
        "max_node_turns": 5, "max_turn_transition": "end_giveup", "interruptible": True}

COMMON_INTENTS = ["pay", "agent", "dispute", "third_party", "out_of_scope", "done"]
COMMON_DESC = ("pay: ödemek istiyor veya nasıl/nereden ödeyeceğini soruyor. agent: müşteri temsilcisi/insan istiyor. "
    "dispute: borca itiraz ediyor ya da yaptığı ödeme görünmüyor diyor. third_party: başka birinin (eşinin, annesinin...) kartı için bilgi/işlem istiyor. "
    "out_of_scope: faiz, limit, puan, taksit, kredi gibi bu görüşmenin dışında bir konu. done: başka bir şey istemiyor, teşekkür ediyor, vedalaşıyor, menüye dönmek istiyor. ")
def common_routes(var): return [(var, "pay", "end_pay"), (var, "agent", "end_agent"), (var, "dispute", "end_dispute"),
                                (var, "third_party", "end_security"), (var, "out_of_scope", "end_oos"), (var, "done", "end_menu")]

def endnode(name, text):
    N[name] = {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "transitions": [],
        "terminal": {"type": "function", "function": {"name": name, "handler": "__function__:end_call", "parameters": {"type": "object", "properties": {
            "message_mode": {"type": "string", "default": "custom"}, "spoken_message": {"type": "string", "default": text}}}}}}

endnode("end_menu", "{{end_text}}")
endnode("end_agent_err", "{{end_text}}")
endnode("end_no_card", SPEC["s_no_card"])
endnode("end_pay", SPEC["s_pay"])
endnode("end_agent", SPEC["s_agent"])
endnode("end_dispute", SPEC["s_dispute"])
endnode("end_security", SPEC["s_security"])
endnode("end_oos", SPEC["s_oos"])
endnode("end_giveup", SPEC["s_giveup"])

# 1. start
codenode("start", r'''
vars['end_text'] = SPEC['s_menu']; vars['say'] = ''
vars['sel_tries'] = 0; vars['week_done'] = 'no'; vars['mail_done'] = 'no'; vars['confirm_tries'] = 0; vars['mail_tries'] = 0
vars['past_req'] = 'no'
''', [], "fetch_cards")
api("fetch_cards", "cards.list", {"customerNo": "{{customerNumber}}", "aiFlow": SPEC["aiFlow"]}, "cards_code")
codenode("cards_code", r'''
import re as _re
st = 'error'
try:
    p, code = resp('fetch_cards')
    rows = {}
    for k in list(vars.keys()):
        m = _re.search(r'fetch_cards_response\.data\.data\.cards\.(\d+)\.([A-Za-z0-9_]+)$', str(k))
        if m: rows.setdefault(int(m.group(1)), {})[m.group(2)] = vars.get(k)
    cards = [rows[i] for i in sorted(rows)]
    vars['cards_json'] = json.dumps(cards, ensure_ascii=False)
    if code == 'FB_IVR_CHANNEL_102' or (code == '1' and not cards): st = 'none'
    elif code == '1':
        if len(cards) == 1:
            if str(cards[0].get('isMainCard')).lower() == 'false': st = 'none'
            else:
                st = 'one'; c = cards[0]
                vars['card_no'] = str(c.get('cardNumber') or ''); vars['card_name'] = str(c.get('productName') or ''); vars['card_last4'] = str(c.get('cardNumberLast4') or '')
        else:
            st = 'multi'
            names = []
            for c in cards:
                n = str(c.get('productName') or '')
                if n and n not in names: names.append(n)
            names = names or [str(c.get('cardNumberLast4')) for c in cards]
            vars['say'] = SPEC['s_select'].replace('{a}', names[0]).replace('{b}', names[1] if len(names) > 1 else names[0])
            vars['select_q'] = vars['say']
except Exception:
    st = 'error'
vars['cards_state'] = st; vars['multi'] = 'yes' if st == 'multi' else 'no'
vars['sel_intent'] = 'none'
if st == 'error': vars['end_text'] = SPEC['s_err']
''', [("cards_state", "none", "end_no_card"), ("cards_state", "one", "fetch_balance"), ("cards_state", "multi", "select_card")], "end_agent_err")

# 2. card selection
talk("select_card", "sel_intent", ["choose", "all_cards"] + COMMON_INTENTS,
     "choose: müşteri bir kart adı ya da kart haneleri söyledi. all_cards: bütün kartların borcunu birden istiyor. " + COMMON_DESC,
     [("sel_intent", "choose", "select_code"), ("sel_intent", "all_cards", "select_code")] + common_routes("sel_intent"),
     extra=[{"name": "card_words", "type": "string", "description": "Müşterinin kartı tarif ederken söylediği kelimeler, aynen (kart adı ve/veya söylediği haneler, rakamla).", "min_confidence": 0.3}])
codenode("select_code", r'''
st = 'ask'
try:
    cards = json.loads(vars.get('cards_json') or '[]')
    words = tr_ascii(str(vars.get('card_words') or ''))
    digs = digits_tr(str(vars.get('card_words') or '')) or ''
    vars['sel_tries'] = int(vars.get('sel_tries') or 0) + 1
    cand = cards
    if vars.get('sel_intent') != 'all_cards':
