def ymd(s):
    try:
        d, m, y = str(s).strip().split('.'); return (int(y), int(m), int(d))
    except Exception: return None
def today():
    n = str(vars.get('now') or '')
    try: return (int(n[0:4]), int(n[5:7]), int(n[8:10]))
    except Exception: return None
def fnum(v):
    try: return float(str(v).replace(',', '.'))
    except Exception: return None
def amt(x):
    x = fnum(x) or 0.0
    neg = x < 0; x = abs(x)
    s = '%.2f' % x
    i, f = s.split('.')
    g = ''
    while len(i) > 3: g = '.' + i[-3:] + g; i = i[:-3]
    r = i + g + ('' if f == '00' else ',' + f)
    return ('eksi ' if neg else '') + r
def resp(node):
    p = node + '_response.data.'
    code = str(vars.get(p + 'result.returnCode') or vars.get(p + 'result.code') or '')
    return p + 'data.', code
def joinve(xs):
    return xs[0] if len(xs) == 1 else ', '.join(xs[:-1]) + ' ve ' + xs[-1]
'''

def api(name, path, body, nxt):
    props = {k: {"type": "string", "default": v} for k, v in body.items()}
    N[name] = {"name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": nxt,
        "on_enter": {"type": "silent"},
        "pre_actions": [{"type": "function", "config": {"timeoutMs": 20000, "maxRetries": 0}, "function": {
            "name": name, "handler": "__function__:api_call", "description": path,
            "parameters": {"type": "object", "properties": {
                "url": {"type": "string", "default": BASE + path},
                "method": {"type": "string", "default": "POST"},
                "headers": {"type": "object", "properties": {"Content-Type": {"type": "string", "default": "application/json"}, "Accept": {"type": "string", "default": "application/json"}}},
                "body": {"type": "object", "required": ["data"], "properties": {
                    "data": {"type": "object", "properties": props},
                    "call": {"type": "object", "properties": {"lang": {"type": "string", "default": "tr"}}}}}}}}}],
        "response_mapping": [], "transitions": [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}]}

def eq(var, val): return {"logic": "or", "conditions": [{"variable": var, "operator": "equals", "operand": val}]}

def codenode(name, body, routes, default, use_lib=False):
    tr = [{"target_node": t, "description": "%s=%s" % (v, val), "condition": eq(v, val)} for (v, val, t) in routes]
    tr.append({"target_node": default, "description": "always", "condition": {"operator": "always"}})
    N[name] = {"name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": default,
        "on_enter": {"type": "silent"},
        "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
            "parameters": {"type": "object", "properties": {"code": {"type": "string", "default": C(body, use_lib)},
                                                            "timeout_ms": {"type": "number", "default": 10000}}}}}],
        "transitions": tr}

TALK = ("Sen Freya Bank'ın sesli asistanısın. Türkçe ve 'siz' diliyle konuş. Az önce müşteriye şu metin okundu:\n\"{{say}}\"\n"
        "Say exactly this text. Never promise a transfer, a callback or any other action that the text does not state. "
        "Müşteri tekrar isterse metni kelimesi kelimesine tekrar et. Anlaşılmayan bir yanıtta yalnızca son soruyu kısaca tekrar sor. "
        "Kart numarasının son dört hanesi dışında hiçbir hanesini asla söyleme. Ödeme kanallarını anlatma. Rakam, tarih veya adres uydurma. "
        "Müşteri şifre veya tam kart numarası söylerse onu tekrarlama ve bankanın asla şifre sormadığını hatırlat.")

def talk(name, enum_name, values, desc, routes, extra=None):
    ex = [{"name": enum_name, "type": "string", "enum_values": ["none"] + values, "description": desc, "min_confidence": 0.5}]
    if extra: ex += extra
    tr = [{"target_node": t, "description": "%s=%s" % (v, val), "condition": eq(v, val)} for (v, val, t) in routes]
    N[name] = {"name": name, "node_type": "conversation", "on_enter": {"type": "tts", "text": "{{say}}"},
        "task_message": TALK, "extraction_schema": ex, "transitions": tr, "tools": [],
        "max_node_turns": 5, "max_turn_transition": "end_giveup", "interruptible": True}

COMMON_INTENTS = ["pay", "agent", "dispute", "third_party", "out_of_scope", "done"]
