    "out_of_scope: faiz, limit, puan, taksit, kredi gibi bu görüşmenin dışında bir konu. done: başka bir şey istemiyor, teşekkür ediyor, vedalaşıyor, menüye dönmek istiyor. ")
def common_routes(var): return [(var, "pay", "end_pay"), (var, "agent", "end_agent"), (var, "dispute", "end_dispute"),
                                (var, "third_party", "end_security"), (var, "out_of_scope", "end_oos"), (var, "done", "end_menu")]

def endnode(name, text):
    N[name] = {"name": name, "node_type": "end_call", "on_enter": {"type": "silent"}, "disable_inactivity_monitor": True, "transitions": [],
        "terminal": {"type": "function", "function": {"name": name, "handler": "__function__:end_call", "parameters": {"type": "object", "properties": {
            "message_mode": {"type": "string", "default": "custom"}, "spoken_message": {"type": "string", "default": text}}}}}}

endnode("end_menu", "{{end_text}}")
